sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') return;
    var ga = new GlideAjax('x_snc_vendor.VendorRiskAjax');
    ga.addParam('sysparm_name', 'isDuplicateTaxId');
    ga.addParam('sysparm_tax_id', newValue);
    ga.addParam('sysparm_current_id', g_form.getUniqueValue());
    ga.getXMLAnswer(function(answer) {
        if (answer == 'true') {
            g_form.clearValue('tax_id');
            g_form.showFieldMsg('tax_id', 'A request with this Tax ID already exists.', 'error');
        }
    });
}
